document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function s(n){return`${n.toFixed(1)}%`}function e(n,s,e,a="info"){return`\n      <div class="insight-card ${a}">\n        <h6>${n}</h6>\n        <div class="metric-value">${s}</div>\n        <div class="metric-subtitle">${e}</div>\n      </div>\n    `}const a=document.getElementById("carwash-form"),i=document.getElementById("carwash-result");a&&a.addEventListener("submit",function(a){a.preventDefault();const t=document.getElementById("wash-type").value,o=parseInt(document.getElementById("wash-bays").value),r=parseFloat(document.getElementById("land-cost").value),l=parseFloat(document.getElementById("equipment-cost").value),c=parseFloat(document.getElementById("additional-costs").value),d=parseFloat(document.getElementById("avg-service-price").value),p=parseFloat(document.getElementById("high-season-cars").value),u=parseFloat(document.getElementById("low-season-cars").value),v=parseFloat(document.getElementById("high-season-months").value),m=parseFloat(document.getElementById("staff-costs").value),g=parseFloat(document.getElementById("utilities").value),h=parseFloat(document.getElementById("supplies").value),w=parseFloat(document.getElementById("other-expenses").value);if(o<=0||d<=0||p<=0||u<=0)return i.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const y=r+l+c,b=12-v,$=p*d*30,f=u*d*30,k=$*v,I=f*b,E=k+I;let B=.08;"manual"===t&&(B=.15),"tunnel"===t&&(B=.12),"touchless"===t&&(B=.1);const x=E*B,F=E+x,A=m+g+h+w,L=12*A,C=F-L,P=C/12,M=C/F*100,S=y/C,D=C/y*100,O=F/o,R=(p*v+u*b)/12,T=Math.max(p,u)*d*30*12,z=E/T*100;let U="info";C<0?U="warning":M>35&&(U="success");let W="info";D<20?W="warning":D>35&&(W="success");let H="info";z<60?H="warning":z>80&&(H="success");const V={"self-service":"Self-Service",manual:"Manual Wash",tunnel:"Tunnel Wash",touchless:"Touchless Wash"};i.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🚗 Car Wash Business Plan Analysis</h3>\n          <div class="wash-type-indicator">\n            <span class="wash-type-badge">${V[t]}</span>\n          </div>\n          \n          <div class="insight-cards">\n            ${e("💰 Total Investment",n(y),"Initial capital required","info")}\n            ${e("📈 Monthly Profit",n(P),`Margin: ${s(M)}`,U)}\n            ${e("⏱️ Payback Period",`${S.toFixed(1)} years`,`ROI: ${s(D)}`,S<=3?"success":"warning")}\n            ${e("🎯 Capacity Utilization",s(z),"Efficiency rate",H)}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Land/lease and site preparation</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment and setup</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Licenses, permits and connections</span>\n                  <span>${n(c)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(y)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Annual Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>High season (${v} months × ${p} cars/day)</span>\n                  <span>${n(k)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Low season (${b} months × ${u} cars/day)</span>\n                  <span>${n(I)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (detailing, interior)</span>\n                  <span>${n(x)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Annual Revenue</strong></span>\n                  <span><strong>${n(F)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Staff (washers, manager)</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities (water, electric)</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Supplies (soap, chemicals)</span>\n                  <span>${n(h)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Other expenses</span>\n                  <span>${n(w)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(A)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Bay Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per bay: <strong>${n(O)}/year</strong><br>\n                Average price: <strong>${n(d)}/car</strong><br>\n                Cars per day: <strong>${R.toFixed(0)} units</strong>\n              </div>\n            </div>\n            <div class="insight-card ${C>0?"success":"warning"}">\n              <h6>📊 Seasonal Analysis</h6>\n              <div class="metric-subtitle">\n                High season: <strong>${n($)}/month</strong><br>\n                Low season: <strong>${n(f)}/month</strong><br>\n                Variance: <strong>${s(($-f)/f*100)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${P>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(C)}</strong><br>\n                Weekly profit: <strong>${n(C/52)}</strong><br>\n                Daily profit: <strong>${n(C/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                Maximum revenue: <strong>${n(T)}/year</strong><br>\n                Growth reserve: <strong>${s(100-z)}</strong><br>\n                At full capacity: <strong>+${n(T-E)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${M<25?"<li>⚠️ Low profitability. Consider increasing prices or reducing costs.</li>":""}\n              ${z<60?"<li>📍 Low utilization. Improve marketing or expand services.</li>":""}\n              ${S>4?"<li>⏰ Long payback period. Optimize startup costs or increase revenue.</li>":""}\n              ${z>85?"<li>✅ High utilization! Consider price increases or expansion.</li>":""}\n              ${M>40?"<li>🎉 Excellent profitability! Consider additional locations.</li>":""}\n              <li>🧽 Implement additional services: detailing, interior cleaning, waxing.</li>\n              <li>📱 Launch mobile app for booking and cashless payments.</li>\n              <li>🎯 Introduce loyalty programs for regular customers.</li>\n              <li>⏰ Optimize operating hours based on peak demand patterns.</li>\n              <li>🤝 Establish corporate contracts with taxi and logistics companies.</li>\n              <li>⭐ Invest in service quality to improve customer reviews.</li>\n              <li>🌱 Consider eco-friendly technologies to attract conscious customers.</li>\n              <li>📊 Implement analytics system to optimize bay utilization.</li>\n              <li>💳 Offer subscription plans for unlimited monthly washes.</li>\n              <li>🚗 Add express service options for time-conscious customers.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.carwashBusinessData={"Car Wash Type":V[t],"Number of Bays":o,"Total Investment ($)":y,"Annual Revenue ($)":F,"Annual Expenses ($)":L,"Annual Profit ($)":C,"Monthly Profit ($)":P,"Profit Margin (%)":M,"Annual ROI (%)":D,"Payback Period (years)":S,"Capacity Utilization (%)":z,"Revenue per Bay ($)":O,"Average Service Price ($)":d,"Average Cars per Day":R}}),window.downloadCSV=function(){if(!window.carwashBusinessData)return;const n=Object.entries(window.carwashBusinessData).map(([n,s])=>`"${n}","${"number"==typeof s?s.toFixed(2):s}"`).join("\n"),s=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),e=document.createElement("a");e.href=URL.createObjectURL(s),e.download="car-wash-business-plan.csv",e.click()}});